<?php
namespace App\Http\Controllers\Api\V1\Admin;
use App\Http\Controllers\Controller;
use App\Models\StaffAssignment;
use App\Models\User;
use App\Services\AuditService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\Rules\Password;
final class UserManagementController extends Controller {
 public function index(): JsonResponse { $users=User::with('roles:id,name')->latest()->paginate(25); return response()->json(['success'=>true,'message'=>'Users.','data'=>['items'=>$users->getCollection()->map(fn($user)=>['id'=>$user->id,'name'=>$user->name,'email'=>$user->email,'role'=>$user->roles->first()?->name]),'pagination'=>['current_page'=>$users->currentPage(),'last_page'=>$users->lastPage(),'total'=>$users->total()]]]); }
 public function store(Request $request): JsonResponse { $validated=$request->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255','unique:users,email'],'password'=>['required','confirmed',Password::min(12)->mixedCase()->numbers()->symbols()],'role'=>['required',Rule::in(['resident','intake-officer','barangay-officer','city-department-officer','system-administrator'])],'barangay_id'=>['nullable','uuid','exists:barangays,id'],'department_id'=>['nullable','uuid','exists:departments,id']]); $user=DB::transaction(function()use($validated){$user=User::create(['name'=>$validated['name'],'email'=>strtolower($validated['email']),'password'=>$validated['password']]);$user->assignRole($validated['role']);if(in_array($validated['role'],['barangay-officer','city-department-officer'],true)){abort_if(empty($validated['barangay_id'])===empty($validated['department_id']),422,'Choose exactly one authorized scope.');StaffAssignment::create(['user_id'=>$user->id,'barangay_id'=>$validated['barangay_id']??null,'department_id'=>$validated['department_id']??null,'is_active'=>true]);}return $user;}); AuditService::record($request,'user.created',$user,null,['role'=>$validated['role']]); return response()->json(['success'=>true,'message'=>'User account created.','data'=>['user'=>['id'=>$user->id,'name'=>$user->name,'email'=>$user->email,'role'=>$user->getRoleNames()->first()]]],201); }
 public function update(Request $request,User $user): JsonResponse { $validated=$request->validate(['role'=>['required',Rule::in(['resident','intake-officer','barangay-officer','city-department-officer','system-administrator'])],'barangay_id'=>['nullable','uuid','exists:barangays,id'],'department_id'=>['nullable','uuid','exists:departments,id']]); DB::transaction(function()use($user,$validated){$user->syncRoles([$validated['role']]); StaffAssignment::where('user_id',$user->id)->update(['is_active'=>false]); if(in_array($validated['role'],['barangay-officer','city-department-officer'],true)){abort_if(empty($validated['barangay_id'])===empty($validated['department_id']),422,'Choose exactly one authorized scope.');StaffAssignment::create(['user_id'=>$user->id,'barangay_id'=>$validated['barangay_id']??null,'department_id'=>$validated['department_id']??null,'is_active'=>true]);}}); AuditService::record($request,'user.role_updated',$user,null,['role'=>$validated['role'],'barangay_id'=>$validated['barangay_id']??null,'department_id'=>$validated['department_id']??null]); return response()->json(['success'=>true,'message'=>'User access updated.','data'=>['user'=>['id'=>$user->id,'name'=>$user->name,'email'=>$user->email,'role'=>$user->getRoleNames()->first()]]]); }
}
